// Research per pub: links, operator and private admin notes. Websites and prices come from web research
// (23-29 Sep 2026) and the research spreadsheet; third-party price leads stay in the notes, never as real prices.
// `notes` is the first research; each later pass is an entry in `updates` that starts with its own dated tag,
// e.g. "[28 Sep 2026 research] ...". The seed appends each update once (it checks for that tag), so research
// reaches a live database without overwriting notes an admin has written.
export const researchTag = update => (update.match(/^\[[^\]]+\]/) || [""])[0];

